import { Component, createMemo, onCleanup, onMount, Show } from "solid-js";

import ContextManager from "#core/ui/context-manager/context-manager.js";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { CrisisPolicies } from "#base/ui/policies/crisis-policies.jsx";
import { GovernmentOverview } from "#base/ui/policies/government-overview.jsx";
import {
	activePolicyTab,
	GovtScreenModel,
	GovtScreenModelContext,
	setActivePolicyTab,
} from "#base/ui/policies/model-government.js";
import { PoliciesModel, PoliciesModelContext } from "#base/ui/policies/model-policies.js";
import { PoliciesAndTraditions } from "#base/ui/policies/policies-and-traditions.jsx";
import { ScreenFrame } from "#base/ui-next/components/screen-frame.jsx";

import style from "#base/ui/policies/screen-policies.scss?url";

export interface GovermentScreenProps {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
}

const GovermentScreenComponent: Component<GovermentScreenProps> = (_props) => {
	const policiesModel = PoliciesModel.get();
	const model = GovtScreenModel.get();
	const audio = useAudio("GovernmentOverview");

	onMount(() => {
		audio("popup-open");
	});

	onCleanup(() => {
		setActivePolicyTab("gov-overview");
	});

	const handleOnClosing = () => {
		audio("popup-close");
	};

	const ornatePanelData = createMemo(() => {
		return {
			...model.data.ornatePanelData,
			topIconSrc: "url(blp:fi_celebration_128)",
		};
	});

	return (
		<GovtScreenModelContext.Provider value={model}>
			<PoliciesModelContext.Provider value={policiesModel}>
				<ScreenFrame
					name="Government Screen"
					panelContext="screen-policies"
					audioContext="GovernmentScreen"
					title="LOC_UI_MINI_MAP_GOVERNMENT"
					ornatePanelData={ornatePanelData()}
					onClosing={handleOnClosing}
					doNotStretch={true}
				>
					<Tab
						activeTab={activePolicyTab}
						class="w-full relative flex flex-col flex-auto pointer-events-auto"
					>
						<Tab.TabList
							class="min-w-187 self-center text-base font-base policies__tab-bar"
							nextHotkey="nav-next"
							previousHotkey="nav-previous"
						/>
						<Tab.Output />
						<Tab.Item
							name="gov-overview"
							title={() => "LOC_UI_POLICIES_OVERVIEW_TAB"}
							body={() => (
								<GovernmentOverview
									name="gov-overview"
									id="gov-overview"
									class="flex flex-auto"
								/>
							)}
						/>
						<Tab.Item
							name="policies-and-traditions"
							title={() => "LOC_UI_POLICIES_POLICIES_TAB"}
							body={() => (
								<PoliciesAndTraditions
									name="policies-and-traditions"
									id="policies-and-traditions"
									class="flex flex-auto"
								/>
							)}
						/>
						<Show when={model.data.displayCrisisTab()}>
							<Tab.Item
								name="crisis-policies"
								title={() => "LOC_UI_POLICIES_CRISIS_TAB"}
								body={() => (
									<CrisisPolicies
										name="crisis-policies"
										id="crisis-policies"
										class="flex flex-auto"
									/>
								)}
							/>
						</Show>
					</Tab>
				</ScreenFrame>
			</PoliciesModelContext.Provider>
		</GovtScreenModelContext.Provider>
	);
};

window.addEventListener("hotkey-open-traditions", () => {
	if (ContextManager.isCurrentClass("screen-policies")) {
		ContextManager.pop("screen-policies");
	} else {
		ContextManager.push("screen-policies", { singleton: true, createMouseGuard: true });
	}
});

defineLegacyComponent(
	"screen-policies",
	{
		classNames: ["screen-policies", "fullscreen"],
	},
	(_attrs, _element) => {
		Input.setActiveContext(InputContext.Shell);
		return <GovermentScreenComponent />;
	},
);

export const PoliciesScreen = ComponentRegistry.register({
	name: "PoliciesScreen",
	styles: [style],
	createInstance: GovermentScreenComponent,
});
